#!/usr/bin/env bash
# Rehearse deploy-ui.sh and its rollback on a COPY of a UI directory, served by fake_ui_server.py
# (never a real bot, never a real installed directory).
#
#   test-deploy-ui.sh                          synthetic old UI and synthetic new build
#   test-deploy-ui.sh --installed-copy DIR     use DIR (a copy you made) as the old UI
#   test-deploy-ui.sh --dist DIR               use a real build (pnpm build) as the new UI
#
# Exit code 0 when every check passed.
# shellcheck disable=SC2012,SC2010  # file names here are generated by this test
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
deploy=$here/../deploy-ui.sh
work=$(mktemp -d)
copy="" dist=""
while [ $# -gt 0 ]; do
  case "$1" in
    --installed-copy) copy=$2; shift 2 ;;
    --dist) dist=$2; shift 2 ;;
    *) echo "unknown option $1" >&2; exit 2 ;;
  esac
done

server_pid=""
cleanup() {
  [ -n "$server_pid" ] && kill "$server_pid" 2>/dev/null || true
  rm -rf "$work"
}
trap cleanup EXIT

pass=0
check() { # check DESCRIPTION COMMAND...
  local what=$1; shift
  if "$@" >/dev/null 2>&1; then pass=$((pass + 1)); echo "ok   $what"; else echo "FAIL $what" >&2; exit 1; fi
}
fails() { ! "$@"; }

# ---- the UI directory under test (always a copy inside $work)
installed=$work/ui/installed
mkdir -p "$work/ui"
if [ -n "$copy" ]; then
  [ "$(cd "$copy" && pwd -P)" != "$(cd "$(dirname "$0")" && pwd -P)" ] || exit 2
  cp -a "$copy" "$installed"
else
  mkdir -p "$installed/assets"
  printf '<html><script src="/assets/app-OLD1.js"></script></html>' >"$installed/index.html"
  echo 'old app' >"$installed/assets/app-OLD1.js"
  echo old-fav >"$installed/favicon.ico"
  printf '/*  /index.html  200' >"$installed/_redirects"
  printf '0.8.0-old' >"$installed/.uiversion"
fi
old_marker=$(tr -d '\n' <"$installed/.uiversion")
cp -a "$installed" "$work/original"

# ---- the new build
if [ -z "$dist" ]; then
  dist=$work/dist
  mkdir -p "$dist/assets"
  printf '<html><link href="/assets/app-NEW2.css" rel="stylesheet"><script type="module" src="/assets/app-NEW2.js"></script></html>' >"$dist/index.html"
  echo 'new app' >"$dist/assets/app-NEW2.js"
  echo 'new css' >"$dist/assets/app-NEW2.css"
  echo 'map' >"$dist/assets/app-NEW2.js.map"
  echo new-fav >"$dist/favicon.ico"
fi
new_marker=2.0.0-rehearsal

# ---- the stand-in for the bot
python3 "$here/fake_ui_server.py" "$installed" "$work/port" &
server_pid=$!
for _ in $(seq 1 50); do [ -s "$work/port" ] && break; sleep 0.1; done
port=$(cat "$work/port")
url=http://127.0.0.1:$port
echo "rehearsal on $installed, served on $url"

served_version() { curl -s "$url/ui_version"; }
check "before: /ui_version is the old marker" bash -c "curl -s $url/ui_version | grep -q '\"$old_marker\"'"

# ---- refusals
check "refuses without --target" fails "$deploy" --dist "$dist" --version x
check "refuses a missing target" fails "$deploy" --target "$work/nope" --dist "$dist" --version x
check "refuses a bad version" fails "$deploy" --target "$installed" --dist "$dist" --version 'a b'
check "refuses with nothing to deploy" fails "$deploy" --target "$installed" --version x

# ---- dry run
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker" --url "$url" --dry-run
check "dry run writes nothing" diff -r "$work/original" "$installed"
check "dry run makes no backup" fails bash -c "ls $installed.bak.* "

# ---- deploy
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker" --url "$url"
bak=$(ls -d "$installed".bak.* | tail -n1)
check "backup is an exact copy of the old UI" diff -r "$work/original" "$bak"
check "index.html is the new one" cmp "$dist/index.html" "$installed/index.html"
check "marker written" bash -c "[ \"\$(cat $installed/.uiversion)\" = $new_marker ]"
check "served marker is the new one" bash -c "curl -s $url/ui_version | grep -q '\"$new_marker\"'"
check "served index.html is the new one" bash -c "[ \"\$(curl -s $url/ | sha256sum)\" = \"\$(sha256sum < $dist/index.html)\" ]"
check "every old asset is still served (open tabs keep working)" bash -c "cd $work/original && find . -type f -not -name index.html -not -name .uiversion | while read -r f; do curl -sf \"$url/\${f#./}\" >/dev/null || exit 1; done"
check "every new asset is copied intact" bash -c "cd $dist && find . -type f -not -name index.html -not -name '*.map' -not -name .uiversion | while read -r f; do cmp -s \"\$f\" \"$installed/\$f\" || exit 1; done"
check "no source map was added" bash -c "[ \$(cd $installed && find . -name '*.map' | wc -l) = \$(cd $work/original && find . -name '*.map' | wc -l) ]"
check "no temporary file left" fails bash -c "find $installed -name '*.new.*' | grep -q ."

# ---- idempotent
n_before=$(ls -d "$installed".bak.* | wc -l)
out=$("$deploy" --target "$installed" --dist "$dist" --version "$new_marker" --url "$url")
check "second run says already deployed" bash -c "echo '$out' | grep -q 'already deployed'"
check "second run makes no new backup" bash -c "[ $(ls -d "$installed".bak.* | wc -l) = $n_before ]"

# ---- rollback
"$deploy" --target "$installed" --rollback --url "$url"
check "rollback: index.html is the old one" cmp "$work/original/index.html" "$installed/index.html"
check "rollback: marker is the old one" bash -c "[ \"\$(cat $installed/.uiversion)\" = $old_marker ]"
check "rollback: served marker is the old one" bash -c "curl -s $url/ui_version | grep -q '\"$old_marker\"'"
check "rollback: served index.html is the old one" bash -c "[ \"\$(curl -s $url/ | sha256sum)\" = \"\$(sha256sum < $work/original/index.html)\" ]"
check "rollback: every original file is back" bash -c "cd $work/original && find . -type f | while read -r f; do cmp -s \"\$f\" \"$installed/\$f\" || exit 1; done"
check "rollback keeps the backup" test -d "$bak"
"$deploy" --target "$installed" --rollback --url "$url" >/dev/null
check "rollback twice is fine" cmp "$work/original/index.html" "$installed/index.html"
"$deploy" --target "$installed" --rollback --exact --url "$url"
check "rollback --exact: tree identical to the original" diff -r "$work/original" "$installed"

# ---- a build whose index.html names a missing file is refused and undone
bad=$work/bad
cp -a "$dist" "$bad"
printf '<html><script src="/assets/does-not-exist.js"></script></html>' >"$bad/index.html"
check "deploy of a broken build fails" fails "$deploy" --target "$installed" --dist "$bad" --version broken --url "$url"
check "broken build: index.html restored" cmp "$work/original/index.html" "$installed/index.html"
check "broken build: marker restored" bash -c "[ \"\$(cat $installed/.uiversion)\" = $old_marker ]"
check "broken build: served marker restored" bash -c "curl -s $url/ui_version | grep -q '\"$old_marker\"'"

# ---- backups are pruned to --keep
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker.a" --url "$url" --keep 2 >/dev/null
sleep 1
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker.b" --url "$url" --keep 2 >/dev/null
check "--keep 2 leaves two backups" bash -c "[ $(ls -d "$installed".bak.* | wc -l) = 2 ]"

# ---- B109: backups made by hand are neither pruned nor chosen by --rollback
cp -a "$work/original" "$installed.bak.20260521_084930"
cp -a "$work/original" "$installed.bak.99991231_235959"
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker.c" --url "$url" --keep 1 >/dev/null
sleep 1
"$deploy" --target "$installed" --dist "$dist" --version "$new_marker.d" --url "$url" --keep 1 >/dev/null
check "--keep 1 leaves one backup of the script" bash -c "[ \$(ls -d $installed.bak.????????T??????Z* | wc -l) = 1 ]"
check "a manual backup was not pruned" test -d "$installed.bak.20260521_084930"
check "a later-sorting manual backup was not pruned" test -d "$installed.bak.99991231_235959"
"$deploy" --target "$installed" --rollback --url "$url" >/dev/null
check "rollback restores the last deploy, not the manual copy" bash -c "[ \"\$(cat $installed/.uiversion)\" = $new_marker.c ]"

echo "all $pass checks passed"
